class LifoQueue(queue.Queue):
    pass

    def _init(self, _):
        pass

        self.queue = collections.deque()



    def _qsize(self, len=len):
        pass

        return len(self.queue)



    def _put(self, item):
        pass

        self.queue.append(item)



    def _get(self):
        pass

        return self.queue.pop()




